import { normaliseText } from "../normalise";

export type LeafKind = "fts" | "substring";

/** Choose FTS vs substring by script content of the term. */
export function classifyLeaf(term: string): LeafKind {
  // Han, Hiragana, Katakana, Arabic blocks → substring
  if (/[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]/.test(term)) {
    return "substring";
  }
  if (/[\u3040-\u30FF\u3400-\u9FFF\uF900-\uFAFF]/.test(term)) {
    return "substring";
  }
  return "fts";
}

export function escapeIlike(term: string): string {
  return term.replace(/\\/g, "\\\\").replace(/%/g, "\\%").replace(/_/g, "\\_");
}

export function normaliseLeafTerm(term: string): string {
  return normaliseText(term);
}
import { isEnglish, needsTranslation } from "./language";

export function languageDisplayName(code: string | null | undefined): string {
  if (!code?.trim()) return "unknown";
  try {
    const dn = new Intl.DisplayNames(["en"], { type: "language" });
    const primary = code.trim().split(/[-_]/)[0]!;
    return dn.of(primary) ?? code;
  } catch {
    return code;
  }
}

export type TranslationPageState =
  | { kind: "not_needed" }
  | { kind: "translated"; lowTrust: boolean; mock: boolean }
  | { kind: "pending" }
  | { kind: "paused" }
  | { kind: "failed"; reason: string }
  | { kind: "no_content" }
  | { kind: "looks_english" }
  | { kind: "load_error" };

export function selectTranslationPageState(opts: {
  language: string | null;
  translationRow: {
    headline_en: string | null;
    body_en: string | null;
    flags?: string[] | null;
  } | null;
  job: { state: string; reason_code: string | null } | null;
  enrichment: { trust: string; origin: string } | null;
  loadFailed?: boolean;
}): TranslationPageState {
  if (opts.loadFailed) return { kind: "load_error" };
  if (isEnglish(opts.language)) return { kind: "not_needed" };
  if (!needsTranslation(opts.language) && !opts.job) return { kind: "not_needed" };

  if (opts.translationRow) {
    const flags = opts.translationRow.flags ?? [];
    if (flags.includes("lang_unknown") && opts.enrichment) {
      // model may have reported English — still show translation if we have one
    }
    return {
      kind: "translated",
      lowTrust: opts.enrichment?.trust === "low",
      mock: opts.enrichment?.origin === "mock",
    };
  }

  if (!opts.job) {
    // Older article, not scheduled (ADR-0028) — show as pending-style load? Use pending message.
    return { kind: "pending" };
  }

  switch (opts.job.state) {
    case "queued":
    case "running":
    case "failed_retryable":
      return { kind: "pending" };
    case "deferred_budget":
      return { kind: "paused" };
    case "skipped_no_content":
      return { kind: "no_content" };
    case "dead":
      return { kind: "failed", reason: opts.job.reason_code ?? "invalid_output" };
    case "succeeded":
      // Race: job succeeded but row missing
      return { kind: "load_error" };
    default:
      return { kind: "pending" };
  }
}
"use client";

import { useState } from "react";
import Link from "next/link";
import { TextBlock } from "./TextBlock";
import { MatchedInTag } from "./MatchedInTag";
import { strings } from "@/lib/ui/strings";
import { needsTranslation } from "@/lib/translate/language";

type Derived = {
  field: string;
  value: string;
  confidence_norm: string | number | null;
  confidence_origin: string;
  method: string;
  scale_min?: number;
  scale_max?: number;
  extra?: unknown;
};

type Job = { part: string; state: string; reason_code?: string | null };

export function ArticleCard({ article }: { article: Record<string, unknown> }) {
  const [whyOpen, setWhyOpen] = useState<string | null>(null);
  const [showBody, setShowBody] = useState(false);
  const headline = article.headline as string | null;
  const headlineEn = article.headline_en as string | null | undefined;
  const matchedIn = article.matched_in as string | undefined;
  const lang = article.language as string;
  const flags = (article.flags as string[]) ?? [];
  const derived = (article.derived as Derived[]) ?? [];
  const jobs = (article.jobs as Job[]) ?? [];
  const sentiment = derived.find((d) => d.field === "sentiment");
  const summary = derived.find((d) => d.field === "summary");
  const topics = derived.filter((d) => d.field === "topic");
  const sentJob = jobs.find((j) => j.part === "sentiment");
  const sumJob = jobs.find((j) => j.part === "summary_topics");
  const trJob = jobs.find((j) => j.part === "translation");

  const mock = derived.some((d) => d.confidence_origin === "mock");
  const translationMock = trJob?.state === "succeeded" && mock;
  const lowTrust = flags.includes("possible_prompt_injection");

  function enrichmentLabel(job: Job | undefined, hasValue: boolean): string {
    if (hasValue) return "";
    if (!job) return "Pending";
    switch (job.state) {
      case "queued":
      case "running":
        return "Pending";
      case "deferred_budget":
        return "Paused";
      case "dead":
        return "Unavailable";
      case "skipped_no_content":
        return "Not applicable";
      case "failed_retryable":
        return "Pending";
      default:
        return "Pending";
    }
  }

  const summaryText = summary?.value
    ? summary.value
    : sumJob?.state === "deferred_budget"
      ? "Enrichment paused: daily budget reached"
      : sumJob?.state === "dead"
        ? "Enrichment unavailable"
        : sumJob?.state === "skipped_no_content"
          ? "No text to analyse"
          : sumJob?.state === "failed_retryable"
            ? "Enrichment delayed, retrying"
            : "Not yet enriched";

  return (
    <article className="border border-border bg-surface rounded p-4 space-y-2">
      {headline ? (
        <h2 className="text-base font-semibold">
          <TextBlock text={headline} lang={lang} as="span" />
        </h2>
      ) : (
        <h2 className="text-base italic text-muted" title="The source did not supply a headline">
          {strings.noHeadline}
        </h2>
      )}
      {needsTranslation(lang) && headlineEn && (
        <p className="text-sm text-muted" lang="en">
          {strings.englishHeadline(headlineEn)}
        </p>
      )}
      {(matchedIn === "translation" || matchedIn === "both") && (
        <MatchedInTag
          side={matchedIn === "both" ? "both" : "translation"}
          mock={Boolean(translationMock)}
        />
      )}
      <p className="text-xs text-muted">
        {String(article.source)} · {lang.toUpperCase()} ·{" "}
        <time dateTime={String(article.published_at)} title={String(article.published_at)}>
          {new Date(String(article.published_at)).toISOString().replace("T", " ").slice(0, 16)} UTC
        </time>
      </p>
      <div className="flex flex-wrap gap-2 text-xs">
        {flags.includes("markup_removed") && (
          <span className="border border-border px-1.5 py-0.5 rounded">Markup removed</span>
        )}
        {lowTrust && (
          <span className="border border-warn text-warn px-1.5 py-0.5 rounded">
            Possible prompt injection
          </span>
        )}
      </div>
      <div>
        <p className="text-xs text-muted mb-0.5">
          {mock ? strings.mockOutput : strings.aiSummary}
        </p>
        <TextBlock text={summaryText} lang={lang} className="text-sm" />
      </div>
      <div className="flex flex-wrap gap-3 items-center text-sm">
        {sentiment ? (
          <span>
            Sentiment: {sentiment.value}{" "}
            {sentiment.confidence_norm != null && (
              <>
                {Number(sentiment.confidence_norm).toFixed(0)}%
                <button
                  type="button"
                  className="ml-1 underline text-xs"
                  aria-expanded={whyOpen === "sentiment"}
                  onClick={() => setWhyOpen(whyOpen === "sentiment" ? null : "sentiment")}
                >
                  {strings.why}
                </button>
              </>
            )}
            {whyOpen === "sentiment" && (
              <WhyBox
                origin={sentiment.confidence_origin}
                method={sentiment.method}
                raw={sentiment.confidence_norm}
              />
            )}
          </span>
        ) : (
          <span className="text-muted">Sentiment: {enrichmentLabel(sentJob, false)}</span>
        )}
        {topics.length > 0
          ? topics.map((t) => (
              <Link
                key={t.value}
                href={`/?topic=${encodeURIComponent(t.value)}`}
                className="border border-border rounded-full px-2 py-0.5 text-xs no-underline text-foreground"
              >
                {t.value}
                {t.confidence_norm != null ? ` ${Number(t.confidence_norm).toFixed(0)}%` : ""}
              </Link>
            ))
          : (
            <span className="text-muted text-xs">Topics: {enrichmentLabel(sumJob, false)}</span>
          )}
      </div>
      {typeof article.body_excerpt === "string" && article.body_excerpt.length > 0 ? (
        <div>
          <button type="button" className="text-xs underline" onClick={() => setShowBody(!showBody)}>
            {showBody ? "Hide text" : "Show more"}
          </button>
          {showBody ? (
            <TextBlock
              text={article.body_excerpt}
              lang={lang}
              className="mt-1 text-sm whitespace-pre-wrap"
            />
          ) : null}
        </div>
      ) : null}
      <Link href={`/articles/${article.id}`} className="text-sm text-accent">
        Details
      </Link>
    </article>
  );
}

function WhyBox({
  origin,
  method,
  raw,
}: {
  origin: string;
  method: string;
  raw: string | number | null;
}) {
  const explanation =
    origin === "classifier_concentration"
      ? "Classifier confidence measures how decisive the choice was. It is not the chance the label is right."
      : origin === "llm_self_report"
        ? "This confidence is self-reported by the language model."
        : origin === "mock"
          ? "Mock output from the local lexicon adapter (no external API call)."
          : "No confidence available.";
  return (
    <div className="mt-1 text-xs border border-border rounded p-2 bg-background max-w-md">
      <p>{explanation}</p>
      <p className="mt-1 text-muted">
        Origin: {origin} · Method: {method} · Value: {raw}
      </p>
    </div>
  );
}
"use client";

import { useId, useState } from "react";
import { TextBlock } from "./TextBlock";
import { strings } from "@/lib/ui/strings";
import { languageDisplayName } from "@/lib/translate/display";

type Props = {
  sourceLang: string;
  original: { headline: string | null; body: string | null };
  translation: { headline_en: string | null; body_en: string | null };
  trust: "normal" | "low";
  mock: boolean;
  modelInfo: { model: string; promptVersion: string; producedAt: string };
};

export function TranslatedText(props: Props) {
  const [view, setView] = useState<"translated" | "original">("translated");
  const [live, setLive] = useState("");
  const textId = useId();
  const langName = languageDisplayName(props.sourceLang);

  function toggle() {
    const next = view === "translated" ? "original" : "translated";
    setView(next);
    setLive(
      next === "original"
        ? strings.liveOriginal(langName)
        : strings.liveTranslation,
    );
    try {
      navigator.sendBeacon?.(
        "/api/telemetry/translation-view",
        new Blob([JSON.stringify({ view: next })], { type: "application/json" }),
      );
    } catch {
      // silent
    }
  }

  const showingTranslated = view === "translated";
  const headlineTranslated = props.translation.headline_en;
  const headlineOriginal = props.original.headline;
  const activeHeadline = showingTranslated
    ? headlineTranslated ?? headlineOriginal
    : headlineOriginal;
  const headlineNote =
    showingTranslated && !headlineTranslated && headlineOriginal
      ? strings.headlineNotTranslated
      : null;

  const label = props.mock
    ? strings.translationMockLabel
    : showingTranslated
      ? langName !== "unknown"
        ? strings.translationLabel(langName)
        : strings.translationLabelUnknown
      : strings.originalLabel(langName);

  const minHeightHint = Math.max(
    (props.translation.body_en ?? "").length,
    (props.original.body ?? "").length,
  );
  const minPx = Math.min(480, Math.max(120, Math.floor(minHeightHint / 8)));

  return (
    <div className="space-y-3">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 border border-border rounded px-3 py-2 bg-surface">
        <div className="space-y-1 min-w-0">
          <p className="text-sm font-medium">{label}</p>
          {props.trust === "low" && (
            <p className="text-sm text-amber-800" role="alert">
              ⚠ {strings.translationLowTrust}
            </p>
          )}
          <details className="text-xs text-muted">
            <summary className="cursor-pointer">{strings.translationDisclaimer}</summary>
            <p className="mt-1">
              {strings.translationAbout(
                props.modelInfo.model,
                props.modelInfo.producedAt,
                props.modelInfo.promptVersion,
              )}
            </p>
          </details>
        </div>
        <button
          type="button"
          className="min-h-11 px-4 py-2 border border-border rounded text-sm bg-background hover:bg-surface focus-visible:outline focus-visible:outline-2"
          aria-pressed={view === "original"}
          aria-controls={textId}
          aria-label={
            showingTranslated ? "Show original text" : "Show translation"
          }
          onClick={toggle}
        >
          {showingTranslated ? strings.showOriginal : strings.showTranslation}
        </button>
      </div>

      <div aria-live="polite" className="sr-only">
        {live}
      </div>

      {activeHeadline !== undefined && (
        <h1 className="text-xl font-semibold">
          {activeHeadline ? (
            <TextBlock
              text={activeHeadline}
              lang={showingTranslated ? "en" : props.sourceLang}
              as="span"
            />
          ) : (
            <span className="italic text-muted">{strings.noHeadline}</span>
          )}
          {headlineNote && (
            <span className="block text-xs text-muted font-normal mt-1">{headlineNote}</span>
          )}
        </h1>
      )}

      <div id={textId} style={{ minHeight: minPx }} className="relative">
        <div
          className={showingTranslated ? "block" : "invisible absolute inset-0 pointer-events-none"}
          aria-hidden={!showingTranslated}
          aria-label="English translation"
        >
          <TextBlock
            text={props.translation.body_en ?? ""}
            lang="en"
            className="whitespace-pre-wrap text-sm leading-relaxed"
          />
        </div>
        <div
          className={!showingTranslated ? "block" : "invisible absolute inset-0 pointer-events-none"}
          aria-hidden={showingTranslated}
          aria-label={`Original text, ${langName}`}
        >
          <TextBlock
            text={props.original.body ?? ""}
            lang={props.sourceLang}
            className="whitespace-pre-wrap text-sm leading-relaxed"
          />
        </div>
      </div>

      {/* No-JS fallback: original in details (server also emits this) */}
      <noscript>
        <details>
          <summary>Original text</summary>
          <pre className="whitespace-pre-wrap text-sm">{props.original.body}</pre>
        </details>
      </noscript>
    </div>
  );
}
import { strings } from "@/lib/ui/strings";
import type { TranslationPageState } from "@/lib/translate/display";

function failedCopy(reason: string): string {
  if (reason === "too_long") return strings.translationFailedTooLong;
  if (reason === "permanent_failure" || reason === "provider_4xx") {
    return strings.translationFailedRejected;
  }
  if (reason === "attempts" || reason === "max_attempts") {
    return strings.translationFailedAttempts;
  }
  if (reason === "budget_never") return strings.translationFailedBudgetNever;
  return strings.translationFailedChecks;
}

export function TranslationNotice({
  state,
  languageName,
}: {
  state: TranslationPageState;
  languageName?: string;
}) {
  if (state.kind === "not_needed") return null;

  let text = "";
  switch (state.kind) {
    case "pending":
      text = strings.translationPending;
      break;
    case "paused":
      text = strings.translationPaused;
      break;
    case "failed":
      text = failedCopy(state.reason);
      break;
    case "no_content":
      text = strings.translationNoText;
      break;
    case "looks_english":
      text = strings.translationLooksEnglish;
      break;
    case "load_error":
      text = strings.translationLoadError;
      break;
    case "translated":
      return null;
  }

  return (
    <div className="rounded border border-border bg-surface px-3 py-2 text-sm space-y-1" role="status">
      <p>{text}</p>
      {state.kind === "pending" && (
        <p className="text-muted text-xs">{strings.checkBackShortly}</p>
      )}
      {languageName && state.kind !== "no_content" && (
        <p className="text-muted text-xs">Language: {languageName}</p>
      )}
      {state.kind === "failed" && (
        <a href="#trail" className="underline text-xs">
          Details
        </a>
      )}
    </div>
  );
}

