import { scan, type Token } from "./scan";

export type AstNode =
  | { type: "term"; value: string; phrase?: boolean; wildcard?: boolean }
  | { type: "and"; left: AstNode; right: AstNode }
  | { type: "or"; left: AstNode; right: AstNode }
  | { type: "and_not"; left: AstNode; right: AstNode };

export type ParseError = {
  code: string;
  message: string;
  position: number;
};

export type ParseResult =
  | { ok: true; ast: AstNode | null; leafCount: number; wildcardCount: number }
  | { ok: false; error: ParseError };

const MAX_CHARS = 500;
const MAX_DEPTH = 8;
const MAX_LEAVES = 20;
const MAX_WILDCARDS = 5;
const MIN_PREFIX = 2;

class Parser {
  tokens: Token[];
  i = 0;
  leafCount = 0;
  wildcardCount = 0;
  depth = 0;

  constructor(tokens: Token[]) {
    this.tokens = tokens;
  }

  peek(): Token {
    return this.tokens[this.i] ?? { kind: "EOF", value: "", start: 0, end: 0 };
  }

  take(): Token {
    const t = this.peek();
    this.i++;
    return t;
  }

  parse(): ParseResult {
    if (this.peek().kind === "EOF") {
      return { ok: true, ast: null, leafCount: 0, wildcardCount: 0 };
    }
    try {
      const ast = this.parseOr();
      if (this.peek().kind !== "EOF") {
        return {
          ok: false,
          error: {
            code: "unexpected_token",
            message: `Unexpected token (position ${this.peek().start})`,
            position: this.peek().start,
          },
        };
      }
      return {
        ok: true,
        ast,
        leafCount: this.leafCount,
        wildcardCount: this.wildcardCount,
      };
    } catch (e) {
      const err = e as ParseError;
      return { ok: false, error: err };
    }
  }

  fail(code: string, message: string, position: number): never {
    throw { code, message, position } satisfies ParseError;
  }

  parseOr(): AstNode {
    let left = this.parseAnd();
    while (this.peek().kind === "OR") {
      this.take();
      if (this.peek().kind === "EOF" || this.peek().kind === "RPAREN") {
        this.fail("dangling_or", `OR needs a term on both sides (position ${this.peek().start})`, this.peek().start);
      }
      const right = this.parseAnd();
      left = { type: "or", left, right };
    }
    return left;
  }

  parseAnd(): AstNode {
    let left = this.parseUnary();
    for (;;) {
      const t = this.peek();
      if (t.kind === "AND") {
        this.take();
        if (this.peek().kind === "NOT") {
          this.take();
          const right = this.parseUnary();
          left = { type: "and_not", left, right };
          continue;
        }
        if (
          this.peek().kind === "EOF" ||
          this.peek().kind === "RPAREN" ||
          this.peek().kind === "OR" ||
          this.peek().kind === "AND"
        ) {
          this.fail(
            "dangling_and",
            `AND needs a term on both sides (position ${t.end})`,
            t.end,
          );
        }
        const right = this.parseUnary();
        left = { type: "and", left, right };
        continue;
      }
      if (
        t.kind === "WORD" ||
        t.kind === "PHRASE" ||
        t.kind === "WILDCARD" ||
        t.kind === "LPAREN"
      ) {
        // implicit AND
        const right = this.parseUnary();
        left = { type: "and", left, right };
        continue;
      }
      break;
    }
    return left;
  }

  parseUnary(): AstNode {
    const t = this.peek();
    if (t.kind === "NOT") {
      this.fail("bare_not", "Use AND NOT to exclude a term", t.start);
    }
    if (t.kind === "AND" || t.kind === "OR") {
      this.fail(
        "dangling_op",
        `${t.value} needs a term on both sides (position ${t.start})`,
        t.start,
      );
    }
    if (t.kind === "LPAREN") {
      this.take();
      this.depth++;
      if (this.depth > MAX_DEPTH) {
        this.fail("depth", "Query nests too deeply", t.start);
      }
      if (this.peek().kind === "RPAREN") {
        this.fail("empty_group", "Empty group", t.start);
      }
      const inner = this.parseOr();
      if (this.peek().kind !== "RPAREN") {
        this.fail("unbalanced", `Missing closing bracket (position ${this.peek().start})`, this.peek().start);
      }
      this.take();
      this.depth--;
      return inner;
    }
    if (t.kind === "PHRASE") {
      this.take();
      if (!t.value.trim()) this.fail("empty_phrase", "Empty phrase", t.start);
      this.leafCount++;
      if (this.leafCount > MAX_LEAVES) this.fail("leaves", "Too many terms", t.start);
      return { type: "term", value: t.value, phrase: true };
    }
    if (t.kind === "WILDCARD") {
      this.take();
      if (t.value.length < MIN_PREFIX) {
        this.fail("short_prefix", "Wildcard prefix must be at least 2 characters", t.start);
      }
      if (/[*]/.test(t.value) || t.value.includes("*")) {
        this.fail("bad_wildcard", "Wildcards go at the end of a single word", t.start);
      }
      this.leafCount++;
      this.wildcardCount++;
      if (this.wildcardCount > MAX_WILDCARDS) this.fail("wildcards", "Too many wildcards", t.start);
      if (this.leafCount > MAX_LEAVES) this.fail("leaves", "Too many terms", t.start);
      return { type: "term", value: t.value, wildcard: true };
    }
    if (t.kind === "WORD") {
      this.take();
      this.leafCount++;
      if (this.leafCount > MAX_LEAVES) this.fail("leaves", "Too many terms", t.start);
      return { type: "term", value: t.value };
    }
    this.fail("unexpected", `Unexpected token (position ${t.start})`, t.start);
  }
}

export function parseQuery(input: string): ParseResult {
  if (input.length > MAX_CHARS) {
    return {
      ok: false,
      error: {
        code: "too_long",
        message: `Query exceeds ${MAX_CHARS} characters`,
        position: 0,
      },
    };
  }
  const trimmed = input.trim();
  if (!trimmed) {
    return { ok: true, ast: null, leafCount: 0, wildcardCount: 0 };
  }
  const tokens = scan(input);
  // Detect unclosed quote: scan leaves PHRASE without closing — check raw
  if ((input.match(/"/g) ?? []).length % 2 === 1) {
    const pos = input.lastIndexOf('"');
    return {
      ok: false,
      error: { code: "unclosed_phrase", message: "Unclosed phrase", position: pos },
    };
  }
  // Reject mid-word wildcards like a*b
  for (const t of tokens) {
    if (t.kind === "WORD" && t.value.includes("*")) {
      return {
        ok: false,
        error: {
          code: "bad_wildcard",
          message: "Wildcards go at the end of a single word",
          position: t.start,
        },
      };
    }
  }
  return new Parser(tokens).parse();
}
import type { AstNode } from "./parse";
import { classifyLeaf, escapeIlike, normaliseLeafTerm } from "./leaf";

export type CompiledQuery = {
  sql: string | null;
  params: unknown[];
  /** Original-side-only predicate (same param indices as sql). */
  originalSql: string | null;
  /** Translation-side EXISTS predicate (same param indices as sql). */
  translationSql: string | null;
};

type Side = "both" | "original" | "translation";

/**
 * Compile AST to a SQL boolean fragment.
 * Positive term leaves match original OR current translation (ADR-0025).
 * The right side of `and_not` matches the original only (ADR-0027).
 */
export function compileAst(ast: AstNode | null, startIndex = 1): CompiledQuery {
  if (!ast) return { sql: null, params: [], originalSql: null, translationSql: null };

  // First pass: collect unique param values in visit order (same as term leaves).
  const params: unknown[] = [];
  let next = startIndex;
  const indexByKey = new Map<string, number>();

  function paramIndex(key: string, value: unknown): number {
    const existing = indexByKey.get(key);
    if (existing !== undefined) return existing;
    params.push(value);
    const i = next;
    next++;
    indexByKey.set(key, i);
    return i;
  }

  function termKey(node: Extract<AstNode, { type: "term" }>): { key: string; value: unknown; kind: string } {
    const kind = classifyLeaf(node.value);
    const norm = normaliseLeafTerm(node.value);
    if (kind === "substring") {
      return { key: `sub:${norm}`, value: `%${escapeIlike(norm)}%`, kind: "substring" };
    }
    if (node.phrase) return { key: `phrase:${norm}`, value: norm, kind: "phrase" };
    if (node.wildcard) {
      const safe = norm.replace(/[^\p{L}\p{N}]+/gu, "");
      return { key: `wild:${safe}`, value: `${safe}:*`, kind: "wildcard" };
    }
    return { key: `term:${norm}`, value: norm, kind: "plain" };
  }

  function translationExists(predicate: string): string {
    return `EXISTS (SELECT 1 FROM article_translations t
      WHERE t.article_id = a.id
        AND t.article_version = a.version
        AND t.superseded_at IS NULL
        AND (${predicate}))`;
  }

  function compileTerm(node: Extract<AstNode, { type: "term" }>, side: Side): string {
    const meta = termKey(node);
    const idx = paramIndex(meta.key, meta.value);
    let orig: string;
    let trPred: string;
    if (meta.kind === "substring") {
      orig = `a.search_text ILIKE $${idx} ESCAPE '\\'`;
      trPred = `t.search_text ILIKE $${idx} ESCAPE '\\'`;
    } else if (meta.kind === "phrase") {
      orig = `a.search_vector @@ phraseto_tsquery('simple', $${idx})`;
      trPred = `t.search_vector @@ phraseto_tsquery('simple', $${idx})`;
    } else if (meta.kind === "wildcard") {
      orig = `a.search_vector @@ to_tsquery('simple', $${idx})`;
      trPred = `t.search_vector @@ to_tsquery('simple', $${idx})`;
    } else {
      orig = `a.search_vector @@ plainto_tsquery('simple', $${idx})`;
      trPred = `t.search_vector @@ plainto_tsquery('simple', $${idx})`;
    }
    if (side === "original") return orig;
    if (side === "translation") return translationExists(trPred);
    return `(${orig} OR ${translationExists(trPred)})`;
  }

  function compile(node: AstNode, side: Side): string {
    switch (node.type) {
      case "and":
        return `(${compile(node.left, side)}) AND (${compile(node.right, side)})`;
      case "or":
        return `(${compile(node.left, side)}) OR (${compile(node.right, side)})`;
      case "and_not":
        if (side === "translation") return compile(node.left, side);
        if (side === "original") {
          return `(${compile(node.left, "original")}) AND NOT (${compile(node.right, "original")})`;
        }
        return `(${compile(node.left, "both")}) AND NOT (${compile(node.right, "original")})`;
      case "term":
        return compileTerm(node, side);
    }
  }

